using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends 2-10 messages grouped together into an album. Currently, only audio, document, photo and video messages can be grouped into an album.
    /// Documents and audio files can be only grouped in an album with messages of the same type. Returns sent messages
    /// </summary>
    public Task<TdLib.TdApi.Objects.Messages> SendMessageAlbumAsync(long chatId = default, MessageTopic topicId = default, InputMessageReplyTo replyTo = default, MessageSendOptions options = default, InputMessageContent[] inputMessageContents = default)
    {

           using var activity =  StartCallActivity("SendMessageAlbumAsync", typeof(SendMessageAlbum).FullName ?? "SendMessageAlbumAsync");

           try
           {
             return client.SendMessageAlbumAsync(chatId, topicId, replyTo, options, inputMessageContents);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
